class Inventory:
    """Counts of items in stock."""

    def __init__(self):
        self._counts = {}

    def add(self, item, quantity=1):
        if quantity <= 0:
            raise ValueError("quantity must be positive")
        self._counts[item] = self._counts.get(item, 0) + quantity

    def count(self, item):
        return self._counts.get(item, 0)

    def items(self):
        return sorted(self._counts)

    def remove(self, item, quantity=1):
        if item not in self._counts:
            raise KeyError(item)
        current = self._counts[item]
        if quantity <= 0 or quantity > current:
            raise ValueError("quantity must be positive and <= current stock")
        new_count = current - quantity
        self._counts[item] = new_count
        if new_count == 0:
            del self._counts[item]

    def total(self):
        return sum(self._counts.values())
