def median(values):
    """Return the median of a list of numbers."""
    if len(values) == 0:
        raise ValueError("empty list")
    sorted_vals = sorted(values)
    n = len(values)
    mid = n // 2
    if n % 2 == 1:
        return sorted_vals[mid]
    else:
        return (sorted_vals[mid-1] + sorted_vals[mid]) / 2.0
