def summarize(rows):
    """rows: list of dicts with 'category' and 'amount' strings. Return {category: total}."""
    totals = {}
    for row in rows:
        cat_raw = row["category"]
        amt_raw = row["amount"]

        # Normalize category: strip and lower case
        norm_cat = cat_raw.strip().lower()
        if norm_cat == "":
            continue

        # Clean amount string by stripping
        amt_clean = amt_raw.strip()
        if amt_clean == "":
            continue

        try:
            val = float(amt_clean)
        except ValueError:
            continue

        # Now add to totals for norm_cat
        if norm_cat in totals:
            totals[norm_cat] += val
        else:
            totals[norm_cat] = val

    # Round each total to two decimal places
    for cat in totals:
        totals[cat] = round(totals[cat], 2)

    return totals
